// Costanti del protocollo
const HEADER = 0x3C;
const OPCODE_TEXT_CMD = 0x13; // 19 dec: Per comandi testuali (es. "reboot")

let opCode;
let dataBuffer;
// --- LOGICA DI SELEZIONE COMANDO ---
// CASO 1: Ingresso Numerico -> È un OpCode diretto (es. 22 per Query, 1 per Start)

if (typeof msg.payload === 'number') {
    opCode = msg.payload;
    dataBuffer = Buffer.alloc(0); // Nessun payload dati, solo l'OpCode
}

// CASO 2: Ingresso Stringa -> È un comando CLI (es. "reboot")
else if (typeof msg.payload === 'string') {
    opCode = OPCODE_TEXT_CMD;
    dataBuffer = Buffer.from(msg.payload);
}

// CASO 3: Ingresso Oggetto personalizzato (per comandi binari complessi)
// Esempio input: { op: 22, data: [0x01, 0x02] }

else if (typeof msg.payload === 'object' && msg.payload.op) {
    opCode = msg.payload.op;

    if (msg.payload.name) {
        // Se l'oggetto ha una proprietà "name", la convertiamo in Buffer
        dataBuffer = Buffer.from(msg.payload.name);
    } else {
        // Altrimenti usiamo il campo data come facevi prima
        dataBuffer = Buffer.from(msg.payload.data || []);
    }
}

else {
    node.error("Tipo di payload non supportato");
    return null;
}

// --- COSTRUZIONE DEL PACCHETTO ---
// 1. Calcola la lunghezza totale del payload protocollo
// La lunghezza nel protocollo Companion include l'OpCode stesso (1 byte) + i dati
const payloadLength = 1 + dataBuffer.length;

// 2. Crea il Buffer della lunghezza (2 bytes, Little Endian)
const lenBuffer = Buffer.alloc(2);
lenBuffer.writeUInt16LE(payloadLength, 0);

// 3. Assembla il pacchetto finale
// [HEADER] [LEN_LOW] [LEN_HIGH] [OPCODE] [DATA...]

msg.payload = Buffer.concat([
    Buffer.from([HEADER]),       // 0x3C
    lenBuffer,                   // Lunghezza (include l'opcode)
    Buffer.from([opCode]),       // L'OpCode effettivo
    dataBuffer                   // I dati (vuoto se è solo un comando diretto)
]);

// Debug visuale per capire cosa stiamo inviando
node.warn(`TX -> OpCode: ${opCode} (0x${opCode.toString(16)}), Len: ${payloadLength}`);

return msg;

// Recupera il buffer
const buf = msg.payload;

// --- Configurazione Uscite ---
// Uscita 1: Oggetto JSON strutturato (Dati utili)
// Uscita 2: Testo semplice (Log/Messaggi Console)
// Uscita 3: Debug Raw (Hex)
let msg1 = null;
let msg2 = null;
let msg3 = null;

// Validazione Buffer
if (!Buffer.isBuffer(buf)) {
    msg2 = { payload: buf, type: "not_buffer" };
    return [msg1, msg2, msg3];
}

// Byte Iniziale (Header)
const header = buf[0];

// --- 1. GESTIONE PROTOCOLLO BINARIO (0x3C o 0x3E) ---
if (header === 0x3C || header === 0x3E) {
    try {
        // Leggi Lunghezza (Bytes 1-2)
        const totalLen = buf.readUInt16LE(1);

        // Leggi OpCode (Byte 3)
        const opCode = buf[3];

        // Estrai il Payload Dati (dal byte 4 in poi)
        // totalLen include l'OpCode, quindi sottraiamo 1 per avere solo i dati
        const dataLen = totalLen - 1;
        const payloadData = buf.subarray(4, 4 + dataLen);

        // Costruiamo l'oggetto di risposta
        const responseObj = {
            dir: (header === 0x3E) ? "RX (Response)" : "TX (Echo)", // Direzione
            opCode: opCode,
            opCodeHex: "0x" + opCode.toString(16).toUpperCase(),
            dataHex: payloadData.toString('hex').toUpperCase(),
            dataInt: (dataLen > 0 && dataLen <= 4) ? payloadData.readUIntLE(0, dataLen) : null
        };

        // --- INTERPRETAZIONE SPECIFICA ---
        // Qui aggiungeremo man mano i casi specifici
        if (opCode === 1) {
             responseObj.meaning = "CMD_APP_START / ACK";
             responseObj.status = (payloadData[0] === 1) ? "OK/Active" : "Fail/Inactive";
        }
        else if (opCode === 22) { // 0x16
             responseObj.meaning = "DEVICE_QUERY_RESPONSE";
             // Se arrivano dati lunghi, qui decodificheremo ID e Versione
        }


        else if (opCode === 8) {
            responseObj.meaning = "CMD_SET_ADVERT_NAME / ACK";
        }
        else if (opCode === 5) {
            responseObj.meaning = "RESP_CODE_SELF_INFO";
            // Nota: qui il dataInt fallirebbe comunque perché SELF_INFO è molto lungo, 
            // ma con la modifica sopra (dataLen <= 4) verrà messo a 'null' correttamente.
        }



        msg1 = { payload: responseObj };

    } catch (e) {
        msg3 = { error: "Errore parsing pacchetto", details: e.message };
    }
} 
// --- 2. GESTIONE TESTO/LOG (Non inizia con 3C o 3E) ---
else {
    msg2 = { payload: buf.toString().trim(), type: "text_log" };
}

// --- 3. DEBUG SEMPRE ATTIVO (Uscita 3) ---
msg3 = msg3 || { 
    rawHex: buf.toString('hex').toUpperCase(), 
    length: buf.length 
};

return [msg1, msg2, msg3];
